input.new_string:
const art = artRows();
const artW = Math.max(...art.map((a) => stripAnsi(a).length));
const cols = process.stdout.columns || 120;
// gutter = push the wordmark to the terminal's right edge; fall back to
// "widest left line + 3" if the terminal is too narrow for that to fit
const LEFTW = Math.max(
  Math.max(...left.map((s) => stripAnsi(s).length)) + 3,
  cols - artW
);
